First, module declaration and signals.

```systemverilog
`timescale 1ns/1ps

module clk_ratio_div_tb;

  logic clk_i;
  logic rst_ni;
  logic en_i;
  logic test_mode_en_i;
  logic [3:0] div_i;
  logic div_valid_i;
  logic div_ready_o;
  logic clk_o;
  logic [3:0] cycl_count_o;

  // DUT instantiation
  clk_ratio_div dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .en_i(en_i),
    .test_mode_en_i(test_mode_en_i),
    .div_i(div_i),
    .div_valid_i(div_valid_i),
    .div_ready_o(div_ready_o),
    .clk_o(clk_o),
    .cycl_count_o(cycl_count_o)
  );

  // Clock generation
  initial begin
    clk_i = 1'b0;
    forever #5 clk_i = ~clk_i;
  end

  // Watchdog
  initial begin
    #4_000_000;
    $display("RESULT: FAIL (watchdog: no forward progress)");
    $finish;
  end

  // Error tracking
  int errors = 0;
  task automatic fail(input string req, input string msg);
    errors++;
    $display("FAIL: %s - %s", req, msg);
  endtask

  task automatic check(input bit cond, input string req, input string msg);
    if (!cond) fail(req, msg);
  endtask
