    div_valid_i = 1'b0;
  endtask
```
Note: `ready_rise_times[start_ready_count]` is the time of the ready rise. Since start_ready_count is the index of the next ready rise. Good.

Measure period and duty from a given posedge time. We'll write a task that takes the first posedge time and measures `num_periods` periods. It will wait for negedge and next posedge for each period. It will check period and high/low widths. For d=0/1, only check period. For d>=2, check high and low.
```systemverilog
  task automatic measure_from_posedge(input time t_start, input logic [3:0] d, input int num_periods, output bit ok);
    time t_pos;
    time t_neg;
    time t_pos_next;
    time period;
    time high;
    time low;
    int i;
    bit w_ok;
    ok = 1;
    t_pos = t_start;
    for (i = 0; i < num_periods; i++) begin
      wait_negedge(200, w_ok, t_neg);
      if (!w_ok) begin
        fail("P1", "timeout waiting for clk_o negedge");
        ok = 0;
        return;
      end
      wait_posedge(200, w_ok, t_pos_next);
      if (!w_ok) begin
        fail("P1", "timeout waiting for clk_o posedge");
        ok = 0;
        return;
      end
      period = t_pos_next - t_pos;
      high = t_neg - t_pos;
      low = t_pos_next - t_neg;
      if (d == 0 || d == 1) begin
        if (period != 10) begin
          fail("P3", $sformatf("period at div %0d is %0t ns, expected 10 ns", d, period));
          ok = 0;
        end
      end else begin
        if (period != d * 10) begin
          fail("P1", $sformatf("period at div %0d is %0t ns, expected %0d ns", d, period, d*10));
          ok = 0;
        end
        if (high != d * 5) begin
          fail("P2", $sformatf("high width at div %0d is %0t ns, expected %0d ns", d, high, d*5));
          ok = 0;
        end
        if (low != d * 5) begin
          fail("P2", $sformatf("low width at div %0d is %0t ns, expected %0d ns", d, low, d*5));
          ok = 0;
        end
      end
      t_pos = t_pos_next;
    end
  endtask
```
Note: `$sformatf` with `%0t` might not work as expected for time? We can use `%0d` and cast to int? `time` is 64-bit. `$sformatf("%0d", period)` might work. We'll use `%0d`. Actually `time` is unsigned 64-bit. `$sformatf("... %0d ...", period)` should work. We'll use `%0d`.

Check counter task. We need to sample cycl_count_o at negedge clk_i. We'll check for `num_cycles` samples. For d=0/1, expect 0. For d>=2, expect sequence modulo d. We need to know the starting value. We can just check that each next value is (prev+1)%d, and all values < d. We'll sample at negedge clk_i. But the counter might update on posedge clk_i. At negedge, it's stable. We'll wait for a negedge, then sample. We need to ensure we are not in gating or disabled. We'll call this after period measurement, while clock is running. We'll sample for d+2 cycles.
```systemverilog
  task automatic check_counter(input logic [3:0] d, input int num_cycles, output bit ok);
    logic [3:0] prev;
    logic [3:0] curr;
    int i;
    ok = 1;
    @(negedge clk_i);
    prev = cycl_count_o;
    for (i = 0; i < num_cycles; i++) begin
      @(negedge clk_i);
      curr = cycl_count_o;
      if (d == 0 || d == 1) begin
        if (curr != 0) begin
          fail("C2", $sformatf("cycl_count_o at div %0d is %0d, expected 0", d, curr));
          ok = 0;
        end
      end else begin
        if (curr >= d) begin
          fail("C1", $sformatf("cycl_count_o at div %0d is %0d, out of range", d, curr));
          ok = 0;
        end
        if (curr != ((prev + 1) % d)) begin
          fail("C1", $sformatf("cycl_count_o at div %0d: %0d -> %0d, expected %0d", d, prev, curr, (prev+1)%d));
          ok = 0;
        end
      end
      prev = curr;
    end
  endtask
```
Note: `%` operator with 4-bit might work. For d=0, we skip modulo. For d>=2, d is up to 15, prev+1 up to 15, modulo d. We need to be careful with d=0: we handle separately.

Now main initial block.

We need to track current_div. Initialize to 0 after reset. We'll use `logic [3:0] current_div;`.

```systemverilog
  initial begin
    logic [3:0] current_div;
    bit ok;
    int wait_cycles;
    time ready_time;
    time t_edge;
    bit stayed_low;
    time t_pos;
    time t_neg;
    time t_pos_next;
    time period;
    time high;
    int i;
    logic [3:0] d;
    logic [3:0] d1, d2;

    // Initialize
    rst_ni = 1'b0;
    en_i = 1'b1;
    div_i = 4'd0;
    div_valid_i = 1'b0;
    test_mode_en_i = 1'b0;
    current_div = 4'd0;

    // Reset
    do_reset();

    // H1: div_ready_o low while div_valid_i low
    for (i = 0; i < 20; i++) begin
      @(negedge clk_i);
      if (div_ready_o !== 1'b0) begin
        fail("H1", "div_ready_o high while div_valid_i low");
        break;
      end
    end

    // Check default divisor 0 (R2, C2)
    wait_posedge(100, ok, t_pos);
    if (!ok) fail("P3", "timeout waiting for default clk_o posedge");
    else begin
      measure_from_posedge(t_pos, 4'd0, 2, ok);
      check_counter(4'd0, 4, ok);
    end

    // Test divisors 1..15
    for (d = 1; d <= 15; d++) begin
      // Request new divisor
      request_div(d, wait_cycles, ok, ready_time);
      if (!ok) begin
        fail("H1", $sformatf("timeout waiting for div_ready_o for div %0d", d));
        continue;
      end
      // Check G1 and G2
      wait_posedge_after_ready(ready_time, 200, ok, t_edge, stayed_low);
      if (!ok) begin
        fail("G1", $sformatf("timeout waiting for first posedge after ready for div %0d", d));
      end else begin
        int limit_ns;
        if (d == 0 || d == 1) limit_ns = 30;
        else limit_ns = 3 * d * 10;
        if (t_edge - ready_time > limit_ns) begin
          fail("G1", $sformatf("gating gap %0d ns > %0d ns for div %0d", t_edge - ready_time, limit_ns, d));
        end
        if (!stayed_low) begin
          fail("G2", $sformatf("clk_o not low during gating for div %0d", d));
        end
      end
      // Measure period and duty from first posedge
      measure_from_posedge(t_edge, d, 3, ok);
      // Check counter
      check_counter(d, d + 2, ok);
      current_div = d;
    end

    // H3: same-value request
    d = current_div; // should be 15
    // Record last posedge before request
    @(negedge clk_i);
    t_pos = last_pos_time;
    request_div(d, wait_cycles, ok, ready_time);
    if (!ok) fail("H3", "same-value request not granted");
    else begin
      if (wait_cycles > 2) begin
        fail("H3", $sformatf("same-value request took %0d cycles, expected immediate", wait_cycles));
      end
      // Wait for next posedge after ready
      wait_posedge_after(ready_time, 200, ok, t_edge);
      if (!ok) fail("H3", "timeout waiting for posedge after same-value request");
      else begin
        // Check no gating: interval from last posedge before request to this posedge <= period + 10
        int period_ns;
        if (d == 0 || d == 1) period_ns = 10;
        else period_ns = d * 10;
        if (t_edge - t_pos > period_ns + 10) begin
          fail("H3", $sformatf("same-value request gated: interval %0d ns > %0d ns", t_edge - t_pos, period_ns + 10));
        end
      end
    end

    // H4: deferred request during gating
    d1 = 4;
    d2 = 8;
    // Start first request to d1
    @(negedge clk_i);
    div_i = d1;
    div_valid_i = 1'b1;
    // Wait for first ready
    int start_ready = ready_rise_count;
    int cnt = 0;
    while (cnt < 200 && ready_rise_count == start_ready) begin
      @(negedge clk_i);
      cnt++;
    end
    if (ready_rise_count == start_ready) begin
      fail("H4", "timeout waiting for first ready in deferred test");
    end else begin
      // First ready rose. Now immediately offer second request while gating.
      @(negedge clk_i);
      div_i = d2;
      // div_valid_i remains high
      start_ready = ready_rise_count;
      cnt = 0;
      while (cnt < 200 && ready_rise_count == start_ready) begin
        @(negedge clk_i);
        cnt++;
      end
      if (ready_rise_count == start_ready) begin
        fail("H4", "second request during gating not accepted");
      end else begin
        // Second ready rose. Check G1 for d2
        ready_time = ready_rise_times[start_ready];
        wait_posedge_after_ready(ready_time, 200, ok, t_edge, stayed_low);
        if (!ok) fail("G1", "timeout waiting for posedge after deferred ready");
        else begin
          int limit_ns = 3 * d2 * 10;
          if (t_edge - ready_time > limit_ns) fail("G1", "deferred gating gap too long");
          if (!stayed_low) fail("G2", "clk_o not low during deferred gating");
        end
        measure_from_posedge(t_edge, d2, 2, ok);
        current_div = d2;
      end
    end
    @(negedge clk_i);
    div_valid_i = 1'b0;

    // Enable tests
    // Configure to 5
    d = 5;
    request_div(d, wait_cycles, ok, ready_time);
    if (!ok) fail("E2", "timeout configuring to 5 for enable test");
    else begin
      wait_posedge_after(ready_time, 200, ok, t_edge);
      if (!ok) fail("E2", "timeout waiting for posedge after config to 5");
      else measure_from_posedge(t_edge, d, 2, ok);
    end

    // E3: disable during high phase
    wait_posedge(200, ok, t_pos);
    if (!ok) fail("E3", "timeout waiting for posedge before disable");
    else begin
      // Set en_i low at next negedge clk_i (still high phase for d=5)
      @(negedge clk_i);
      en_i = 1'b0;
      // Wait for next negedge clk_o (end of high pulse)
      wait_negedge(200, ok, t_neg);
      if (!ok) fail("E3", "timeout waiting for negedge after disable");
      else begin
        high = t_neg - t_pos;
        if (high != 5 * 5) begin
          fail("E3", $sformatf("final high pulse width %0d ns, expected 25 ns", high));
        end
      end
      // Check output stays low for 40 cycles
      for (i = 0; i < 40; i++) begin
        @(negedge clk_i);
        if (clk_o !== 1'b0) begin
          fail("E3", "clk_o not low after disable");
          break;
        end
      end
      // E1: no rising edges for 100 cycles
      int start_pos = pos_count;
      repeat (100) @(negedge clk_i);
      if (pos_count != start_pos) begin
        fail("E1", "clk_o posedge while en_i low");
      end
    end

    // E2: re-enable and check resumes at divisor 5
    @(negedge clk_i);
    en_i = 1'b1;
    wait_posedge(200, ok, t_pos);
    if (!ok) fail("E2", "timeout waiting for posedge after re-enable");
    else measure_from_posedge(t_pos, 4'd5, 2, ok);

    // Reset tests
    // Configure to 4
    d = 4;
    request_div(d, wait_cycles, ok, ready_time);
    if (!ok) fail("R2", "timeout configuring to 4 before reset");
    else begin
      wait_posedge_after(ready_time, 200, ok, t_edge);
      if (!ok) fail("R2", "timeout waiting for posedge after config to 4");
      else measure_from_posedge(t_edge, d, 2, ok);
    end

    // R1: assert reset, check no posedge
    @(negedge clk_i);
    rst_ni = 1'b0;
    int start_pos_rst = pos_count;
    repeat (20) @(negedge clk_i);
    if (pos_count != start_pos_rst) begin
      fail("R1", "clk_o posedge while rst_ni low");
    end
    // Release reset
    @(negedge clk_i);
    rst_ni = 1'b1;
    // R2: default divisor 0
    wait_posedge(200, ok, t_pos);
    if (!ok) fail("R2", "timeout waiting for posedge after reset release");
    else begin
      measure_from_posedge(t_pos, 4'd0, 2, ok);
      check_counter(4'd0, 4, ok);
    end

    // Final result
    if (errors == 0) $display("RESULT: PASS");
    else $display("RESULT: FAIL");
    $finish;
  end
```

We need to check syntax and Verilator compatibility. Issues:

- Declarations inside initial block must be before statements. We declared all variables at top of initial block before statements. Good.
- `int limit_ns;` declared inside an `else` block? In SV, you can declare variables inside a begin/end block, but they must be at the beginning of that block. In my code, inside `else begin int limit_ns; ... end` is okay if it's the first statement. But I have `if (d == 0 || d == 1) limit_ns = 30; else limit_ns = 3 * d * 10;` after declaration. Actually I wrote:
```
